def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h-2):
        for c in range(w-2):
            if grid[r+1][c+1] == 2 and all(
                grid[r+i][c+j] == (2 if (i,j)==(1,1) else 3)
                for i in range(3) for j in range(3)):
                centers.append((r+1,c+1))
    if len(centers) >= 2:
        # Fill horizontal center axes of the marked motifs; copy their cross
        # signal into the other marked motif's column band.
        for r,c in centers:
            for j in range(w):
                if grid[r][j] == 0:
                    out[r][j] = 1
        for r,c in centers:
            for rr,cc in centers:
                if c != cc:
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            y,x=rr+dr,c+dc
                            if 0 <= y < h and 0 <= x < w and grid[y][x] == 0:
                                out[y][x]=1
    elif centers:
        r,c=centers[0]
        # Extend the marker's central cross through the canvas, preserving 2 dividers.
        for y in range(h):
            if grid[y][c] == 0: out[y][c]=1
        for x in range(w):
            if grid[r][x] == 0: out[r][x]=1
    return out
