def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    motifs=[]
    for r in range(h-2):
      for c in range(w-2):
        if grid[r+1][c+1]==2 and all(grid[r+i][c+j]==(2 if (i,j)==(1,1) else 3) for i in range(3) for j in range(3)):
          motifs.append((r+1,c+1))
    # Connect each motif center horizontally, and propagate 1-valued copies in
    # the corresponding cross-blocks defined by the motif center coordinates.
    for r,c in motifs:
      for x in range(w):
        if grid[r][x]==0: out[r][x]=1
    if len(motifs)==1:
      r,c=motifs[0]
      # Along the center column, repeat a three-cell cross pattern in each
      # open 3-row band, with its horizontal bar at the band edge.
      for y in range(h):
        if grid[y][c]==0: out[y][c]=1
      for y in range(h):
        if y%3==2:
          for x in (c-1,c+1):
            if 0<=x<w and grid[y][x]==0: out[y][x]=1
    else:
      for r,c in motifs:
        for rr,cc in motifs:
          if (r,c)!=(rr,cc):
            # Paint a full 3x3 block at the cross-coordinate, but only on empty cells.
            for y in range(rr-1,rr+2):
              for x in range(c-1,c+2):
                if 0<=y<h and 0<=x<w and grid[y][x]==0: out[y][x]=1
    return out
