def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r+1][c+1] == 2 and all(
                grid[r+i][c+j] == (2 if (i, j) == (1, 1) else 3)
                for i in range(3) for j in range(3)
            ):
                centers.append((r+1, c+1))
    if len(centers) >= 2:
        # Project each marked center horizontally. At each crossed divider,
        # draw a 3x3 burst, except at the marked objects themselves.
        for r, c in centers:
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            for x in range(w):
                if grid[r][x] == 2 and (r, x) not in centers:
                    for y in range(r-1, r+2):
                        for xx in range(x-1, x+2):
                            if 0 <= y < h and 0 <= xx < w and (y, xx) != (r, x):
                                out[y][xx] = 1
    elif centers:
        r, c = centers[0]
        # With one object, project vertically; a full horizontal divider
        # receives the same 3x3 burst around its crossing.
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = 1
        for y in range(h):
            if all(v == 2 for v in grid[y]):
                for yy in range(y-1, y+2):
                    for x in range(c-1, c+2):
                        if 0 <= yy < h and 0 <= x < w and (yy, x) != (y, c):
                            out[yy][x] = 1
    return out
