def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r+1][c+1] == 2 and all(
                grid[r+i][c+j] == (2 if (i, j) == (1, 1) else 3)
                for i in range(3) for j in range(3)
            ):
                centers.append((r+1, c+1))
    if len(centers) >= 2:
        # Each symbol projects a horizontal ray from its center. The crossing
        # points with other symbols' center columns become 3x3 marks.
        for r, c in centers:
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
        for r, c in centers:
            for rr, cc in centers:
                if (r, c) != (rr, cc):
                    cy, cx = r, cc
                    for y in range(cy-1, cy+2):
                        for x in range(cx-1, cx+2):
                            if 0 <= y < h and 0 <= x < w and (y, x) != (cy, cx):
                                out[y][x] = 1
    elif centers:
        r, c = centers[0]
        # A lone symbol projects vertically; each full horizontal divider
        # creates a 3x3 mark centered on that intersection.
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = 1
        for y in range(h):
            if all(v == 2 for v in grid[y]):
                for yy in range(y-1, y+2):
                    for x in range(c-1, c+2):
                        if 0 <= yy < h and 0 <= x < w and (yy, x) != (y, c):
                            out[yy][x] = 1
    return out
