def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r+1][c+1] == 2 and all(
                grid[r+i][c+j] == (2 if (i, j) == (1, 1) else 3)
                for i in range(3) for j in range(3)
            ):
                centers.append((r+1, c+1))
    for r, c in centers:
        # The center of each 3x3 mark projects along the axis perpendicular
        # to the existing 2-divider that passes through it.
        vertical_axis = all(grid[y][c] == 2 for y in range(h) if not (r-1 <= y <= r+1))
        horizontal_axis = all(grid[r][x] == 2 for x in range(w) if not (c-1 <= x <= c+1))
        if vertical_axis:
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
        elif horizontal_axis:
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
