                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            ):
                motifs.append((r, c))

    # Find divider lines: full color-2 rows/columns, allowing a 3x3 symbol
    # to interrupt one line at its location.
    row_lines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 2]
    col_lines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 2]

    for r, c in motifs:
        # The symbol sits on a vertical divider if its column contains the long
        # 2-line; that divider projects a horizontal ray (and vice versa).
        vertical_axis = c in col_lines
        horizontal_axis = r in row_lines
        if vertical_axis and not horizontal_axis:
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            for x in col_lines:
                if x == c:
