        elif horizontal_axis:
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            for y in row_lines:
                if y == r:
                    continue
                for yy in range(y - 1, y + 2):
                    for x in range(c - 1, c + 2):
                        if 0 <= yy < h and 0 <= x < w and (yy, x) != (y, c):
