def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[r + dr][c + dc] == (2 if (dr, dc) == (0, 0) else 3)
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            ):
                motifs.append((r, c))
    vlines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 2]
    hlines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 2]
    for r, c in motifs:
        if c in vlines:
            # Ray follows the motif row. Each other vertical divider crossing
            # is a 3x3 cross, with the divider center remaining color 2.
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            for x in vlines:
                if x == c:
                    continue
                for y in range(r - 1, r + 2):
                    for xx in range(x - 1, x + 2):
                        if 0 <= y < h and 0 <= xx < w and grid[y][xx] != 3:
                            out[y][xx] = 1
                out[r][x] = 1 if grid[r][x] != 2 else 2
        elif r in hlines:
            # Ray follows the motif column; horizontal divider crossings likewise
            # receive a 3x3 cross, preserving any original 3 cells.
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            for y in hlines:
                if y == r:
                    continue
                for yy in range(y - 1, y + 2):
                    for x in range(c - 1, c + 2):
                        if 0 <= yy < h and 0 <= x < w and grid[yy][x] != 3:
                            out[yy][x] = 1
                out[y][c] = 2
    return out
