def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[r + dr][c + dc] == (2 if (dr, dc) == (0, 0) else 3)
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            ):
                motifs.append((r, c))

    # Long 2-lines may be interrupted by a 3x3 motif, so permit its three
    # cells along that axis to be missing when identifying divider lines.
    vlines = [c for c in range(w) if sum(grid[y][c] == 2 for y in range(h)) >= h - 5]
    hlines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 5]

    def paint_cross(cy, cx):
        for y in range(cy - 1, cy + 2):
            for x in range(cx - 1, cx + 2):
                if 0 <= y < h and 0 <= x < w and (y, x) != (cy, cx):
                    if grid[y][x] != 3:
                        out[y][x] = 1
        out[cy][cx] = 2

    for r, c in motifs:
        # Determine the divider axis by checking the 2s outside the motif.
        vertical = all(grid[y][c] == 2 for y in range(h) if abs(y - r) > 1)
        horizontal = all(grid[r][x] == 2 for x in range(w) if abs(x - c) > 1)
        if vertical:
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            for x in vlines:
                if x != c:
                    paint_cross(r, x)
        if horizontal:
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            for y in hlines:
                if y != r:
                    paint_cross(y, c)
    return out
